import{_ as t,o as a,c as d,a3 as o}from"./chunks/framework.BveOjhN0.js";const u=JSON.parse('{"title":"Tenant API v1 — Marketplace","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Marketplace | SaleOS Docs"}],["meta",{"property":"og:description","content":"Official documentation for the SaleOS SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.saleos.app/api/tenant-v1-marketplace"}],["meta",{"property":"og:image","content":"https://docs.saleos.app/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Marketplace | SaleOS Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the SaleOS SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.saleos.app/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.saleos.app/api/tenant-v1-marketplace"}]]},"headers":[],"relativePath":"api/tenant-v1-marketplace.md","filePath":"api/tenant-v1-marketplace.md","lastUpdated":1785446554000}'),c={name:"api/tenant-v1-marketplace.md"};function r(n,e,l,s,i,p){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="tenant-api-v1-—-marketplace" tabindex="-1">Tenant API v1 — Marketplace <a class="header-anchor" href="#tenant-api-v1-—-marketplace" aria-label="Permalink to &quot;Tenant API v1 — Marketplace&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1/marketplace</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>marketplace.enabled</code>, plus permission middleware.</p><p>Permissions: <code>marketplace.view</code> (browse), <code>marketplace.purchase</code> (install / subscribe / remove).</p><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to &quot;Modules&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th><th>Behavior</th></tr></thead><tbody><tr><td>GET</td><td><code>/modules</code></td><td><code>marketplace.view</code></td><td>Paginated published catalog (<code>search</code>, <code>category_id</code>)</td></tr><tr><td>GET</td><td><code>/modules/{module}</code></td><td><code>marketplace.view</code></td><td>Detail + install state for the current workspace</td></tr><tr><td>POST</td><td><code>/modules/{module}/purchase</code></td><td><code>marketplace.purchase</code></td><td>Install free module or start paid checkout</td></tr><tr><td>POST</td><td><code>/modules/{module}/confirm-checkout</code></td><td><code>marketplace.purchase</code></td><td>Confirm return from payment gateway</td></tr><tr><td>POST</td><td><code>/modules/{module}/cancel</code></td><td><code>marketplace.purchase</code></td><td>Remove / cancel a non-core installed module</td></tr></tbody></table><h3 id="detail-payload-extras" tabindex="-1">Detail payload extras <a class="header-anchor" href="#detail-payload-extras" aria-label="Permalink to &quot;Detail payload extras&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>already_installed</code></td><td>Active or trial subscription for this workspace</td></tr><tr><td><code>purchase_pending</code></td><td>Pending checkout not yet activated</td></tr><tr><td><code>subscription_status</code> / <code>subscription_source</code></td><td>Current row when present</td></tr><tr><td><code>can_cancel</code></td><td>Tenant may remove it now (not core-included, no blocking dependents)</td></tr><tr><td><code>blocking_dependents</code></td><td>Active modules that hard-depend on this one</td></tr><tr><td><code>required_modules</code> / <code>optional_modules</code> / <code>missing_required_modules</code></td><td>Dependency hints</td></tr></tbody></table><h3 id="cancel-rules" tabindex="-1">Cancel rules <a class="header-anchor" href="#cancel-rules" aria-label="Permalink to &quot;Cancel rules&quot;">​</a></h3><ul><li>Default-included core modules (today: Leads, Tasks) cannot be cancelled by tenants.</li><li>Hard dependents must be removed first (e.g. remove Meetings before Calendar).</li><li>Cancel sets status <code>cancelled</code>, clears entitlements immediately, and cancels any live provider subscription.</li><li>Response includes refreshed <code>modules</code> entitlement slugs for the workspace.</li></ul><p>See <a href="/developer-guide/entitlements">Entitlements</a> for install / cancel policy.</p>',11)])])}const h=t(c,[["render",r]]);export{u as __pageData,h as default};
